  'A one-time code lets your phone or another computer sign in with a passkey of its own.': 'รหัสแบบใช้ครั้งเดียวช่วยให้โทรศัพท์หรือคอมพิวเตอร์เครื่องอื่นของคุณเข้าสู่ระบบด้วยพาสคีย์ของตัวเอง',
