  'Follow the routine ({0})': 'ตามกฎของรูทีน ({0})',
  'Applies to every exercise in this routine that does not set its own rule.': 'ใช้กับทุกท่าในรูทีนนี้ที่ไม่ได้ตั้งกฎเฉพาะของตัวเอง',
  'Step ({0})': 'ขั้นละ ({0})',
  'Step (seconds)': 'ขั้นละ (วินาที)',
  'Reps from': 'จำนวนครั้งเริ่มจาก',
  'No automatic progression': 'ไม่มีการเพิ่มระดับอัตโนมัติ',
  'Linear progression': 'เพิ่มแบบเส้นตรง',
  'Greyskull LP': 'Greyskull LP',
  'Double progression': 'เพิ่มระดับคู่',
  'Add time': 'เพิ่มเวลา',
  'Targets stay where you set them.': 'เป้าหมายจะคงที่ตามที่คุณตั้งไว้',
  'Hit every rep in every set and the weight goes up. Repeated misses trigger a deload.': 'ทำครบทุกครั้งในทุกเซ็ตแล้วน้ำหนักจะเพิ่มขึ้น ถ้าพลาดซ้ำๆ จะลดน้ำหนักลง',
  'Two straight sets plus a final set taken to failure. Beat the target on that set and the weight goes up (twice as much if you double the reps). One failure resets 10 %.': 'สองเซ็ตตามปกติ บวกเซ็ตสุดท้ายที่ทำจนหมดแรง ถ้าทำได้เกินเป้าในเซ็ตนั้น น้ำหนักจะเพิ่มขึ้น (เพิ่มสองเท่าถ้าทำจำนวนครั้งได้สองเท่า) พลาดหนึ่งครั้งจะลดลง 10 %',
  'Work up through a rep range at the same weight. Reach the top of the range in every set and the weight goes up, reps back to the bottom.': 'ไต่ระดับจำนวนครั้งด้วยน้ำหนักเดิม ถ้าถึงจำนวนครั้งสูงสุดในทุกเซ็ต น้ำหนักจะเพิ่มขึ้นและจำนวนครั้งกลับไปเริ่มที่ต่ำสุด',
  'Hold every set for the full duration and the target goes up.': 'ค้างทุกเซ็ตให้ครบเวลา แล้วเป้าหมายจะเพิ่มขึ้น',
  'Nothing logged yet, so this session sets the baseline.': 'ยังไม่มีการบันทึก ครั้งนี้จึงเป็นค่าเริ่มต้น',
  'Held every set for the full time. Target goes up by {0}s.': 'ค้างได้ครบเวลาทุกเซ็ต เป้าหมายเพิ่มอีก {0} วินาที',
  'Short {0} sessions in a row. Back off to {1}s and build up again.': 'ทำไม่ครบเวลา {0} ครั้งติดกัน ลดกลับไปที่ {1} วินาที แล้วค่อยไต่ขึ้นใหม่',
  'Came up short last time. Same target again.': 'ครั้งก่อนทำไม่ถึงเป้า ใช้เป้าหมายเดิมอีกครั้ง',
  'Top of the rep range in every set. {0} {1} more, back to {2} reps.': 'ถึงจำนวนครั้งสูงสุดในทุกเซ็ต เพิ่มอีก {0} {1} แล้วกลับไปที่ {2} ครั้ง',
  'Stuck for {0} sessions. Deload to {1} {2}.': 'ตันมา {0} ครั้งแล้ว ลดน้ำหนัก (deload) ลงเหลือ {1} {2}',
  'Same weight, aim for {0} reps this time.': 'น้ำหนักเดิม รอบนี้ตั้งเป้าที่ {0} ครั้ง',
  'Last set hit {0} reps, twice the target! Take a double jump of {1} {2}.': 'เซ็ตสุดท้ายทำได้ {0} ครั้ง เกินเป้าสองเท่า! เพิ่มน้ำหนักแบบก้าวกระโดด {1} {2}',
  'Every rep last time. {0} {1} more.': 'ครั้งก่อนทำครบทุกครั้ง เพิ่มอีก {0} {1}',
  'Every rep last time. {0} {1} less help.': 'ครั้งก่อนทำครบทุกครั้ง ลดตัวช่วยลง {0} {1}',
  'Top of the rep range in every set. {0} {1} less help, back to {2} reps.': 'ถึงเพดานช่วงจำนวนครั้งทุกเซ็ต ลดตัวช่วยลง {0} {1} แล้วกลับไปที่ {2} ครั้ง',
  'Missed reps. {0} {1} of help while you build back up.': 'ทำไม่ครบจำนวนครั้ง ใช้ตัวช่วย {0} {1} ระหว่างไต่กลับขึ้นมา',
  'Stuck for {0} sessions. Back to {1} {2} of help, then build up again.': 'ตันมา {0} ครั้งแล้ว กลับไปใช้ตัวช่วย {1} {2} แล้วค่อยไต่ขึ้นใหม่',
  'Missed reps {0} sessions running. Reset to {1} {2} and work back up.': 'พลาดจำนวนครั้ง {0} ครั้งติดกัน รีเซ็ตกลับไปที่ {1} {2} แล้วค่อยไต่ขึ้นใหม่',
  'Missed reps. Reset to {0} {1} and work back up.': 'พลาดจำนวนครั้ง รีเซ็ตกลับไปที่ {0} {1} แล้วค่อยไต่ขึ้นใหม่',
  'Missed reps last time. Same weight again ({0} of {1} to go).': 'ครั้งก่อนพลาดจำนวนครั้ง ใช้น้ำหนักเดิมอีกรอบ (เหลืออีก {0} จาก {1})',
  'Bodyweight: every rep last time, so go for {0} this time.': 'น้ำหนักตัว: ครั้งก่อนทำครบทุกครั้ง รอบนี้ลุยที่ {0}',
  'Bodyweight: same target again until every set is clean.': 'น้ำหนักตัว: ใช้เป้าหมายเดิมจนกว่าจะทำได้ครบทุกเซ็ตแบบสวยๆ',

  // --- effort per set (RIR / RPE) ---
  '{0} sets bring an {1} with them. Switch on Effort per set in Settings to see it.': '{0} เซ็ตมาพร้อม {1} เปิด “ความหนักต่อเซ็ต” ในตั้งค่าเพื่อดู',
  '{0} sets bring an {1} with them.': '{0} เซ็ตมาพร้อม {1}',
  'RIR': 'RIR',
  'RPE': 'RPE',
  'Effort per set': 'ความหนักต่อเซ็ต',
  'What are RIR and RPE?': 'RIR และ RPE คืออะไร?',
  'How hard a set was, logged next to weight and reps. Two scales for the same judgement, counted from opposite ends.': 'ความหนักของแต่ละเซ็ต บันทึกคู่กับน้ำหนักและจำนวนครั้ง เป็นสองมาตรวัดของสิ่งเดียวกัน นับจากคนละด้าน',
  'How it felt': 'รู้สึกยังไง',
  'Nothing left, went to failure': 'หมดแรงแล้ว ทำจนสุด',
  'One more rep in the tank': 'ยังเหลืออีกหนึ่งครั้งถ้าจะฝืน',
