  'Most working sets belong close to failure, not at it. Half at the floor and half at the top still average out to a healthy-looking middle.': 'เซ็ตหลักส่วนใหญ่ควรอยู่ใกล้จุดหมดแรง ไม่ใช่ถึงจุดนั้น ครึ่งหนึ่งต่ำสุดกับอีกครึ่งสูงสุด เฉลี่ยแล้วก็ยังดูเหมือนอยู่ตรงกลางสวยๆ อยู่ดี',
