  'For lunges, single-arm rows and the like.': 'สำหรับท่าลันจ์, โรว์แขนเดียว และท่าคล้ายกัน',
  'Top of the range': 'จำนวนครั้งสูงสุด',
  'Reps climb by one whenever every set was clean. Set a ceiling to add sets instead of reps forever.': 'จำนวนครั้งจะเพิ่มทีละหนึ่งเมื่อทำครบทุกเซ็ต ตั้งเพดานไว้เพื่อเปลี่ยนไปเพิ่มเซ็ตแทนการเพิ่มจำนวนครั้งไปเรื่อยๆ',
  'Reps climb to {0}, then a set is added and the reps start over. At {1} sets it asks you to add weight instead.': 'จำนวนครั้งจะเพิ่มถึง {0} จากนั้นจะเพิ่มเซ็ตและเริ่มนับจำนวนครั้งใหม่ พอถึง {1} เซ็ตจะแนะนำให้เพิ่มน้ำหนักแทน',
