  'applied': 'นำไปใช้แล้ว',
  'declined': 'ปฏิเสธแล้ว',
  'Your plan': 'แผนของคุณ',
  'What are you training for?': 'คุณฝึกเพื่ออะไร',
  'Where are you starting from?': 'คุณเริ่มจากจุดไหน',
  'How many days a week?': 'กี่วันต่อสัปดาห์',
  'Which days suit you? (optional)': 'วันไหนสะดวก (ไม่บังคับ)',
  'How long is a session?': 'หนึ่งเซสชันนานเท่าไร',
  'min': 'นาที',
  'The Coach fits the volume to the time you actually have, including rest between sets.': 'โค้ชจะจัดปริมาณให้พอดีกับเวลาที่คุณมีจริง รวมถึงเวลาพักระหว่างเซ็ต',
  'What can you train with?': 'คุณมีอุปกรณ์อะไรบ้าง',
  'Pick everything you have access to. Leave it empty and the Coach will use the whole library.': 'เลือกทุกอย่างที่คุณเข้าถึงได้ หากเว้นว่างไว้ โค้ชจะใช้คลังท่าทั้งหมด',
  'Anything to work around?': 'มีอะไรต้องหลีกเลี่ยงไหม',
  'Injuries, joints that complain, movements you cannot do, or practical limits like training at 6am in a flat.': 'อาการบาดเจ็บ ข้อต่อที่มีปัญหา ท่าที่ทำไม่ได้ หรือข้อจำกัดในชีวิตจริง เช่น ฝึกตอนตีหกในอพาร์ตเมนต์',
  'e.g. “dodgy left shoulder, no barbell overhead press”': 'เช่น “ไหล่ซ้ายไม่ค่อยดี งดดันบาร์เบลเหนือศีรษะ”',
  'If something actually hurts, see a professional. The Coach will program conservatively, but it can’t diagnose anything.': 'หากเจ็บจริง โปรดพบผู้เชี่ยวชาญ โค้ชจะจัดโปรแกรมอย่างระมัดระวัง แต่วินิจฉัยอะไรไม่ได้',
  'Anything else?': 'มีอะไรอีกไหม',
  'Exercises you love': 'ท่าที่คุณชอบ',
  'e.g. “deadlifts, anything with a kettlebell”': 'เช่น “เดดลิฟต์ อะไรก็ได้ที่ใช้เคตเทิลเบล”',
  'Exercises you would rather not': 'ท่าที่คุณไม่อยากทำ',
  'e.g. “I hate lunges”': 'เช่น “ฉันเกลียดลันจ์”',
  'Anything you want the Coach to know': 'อะไรก็ตามที่คุณอยากให้โค้ชรู้',
  'e.g. “I want visible arms progress by spring”': 'เช่น “อยากเห็นแขนพัฒนาชัดเจนภายในฤดูใบไม้ผลิ”',
  'Build my plan': 'สร้างแผนของฉัน',
  'Your plan is live': 'แผนของคุณใช้งานอยู่แล้ว',
  'That proposal can’t be read.': 'ไม่สามารถอ่านข้อเสนอนั้นได้',
  'Discard this plan?': 'ทิ้งแผนนี้หรือไม่',
  'Nothing is saved, and you can ask again anytime.': 'ไม่มีอะไรถูกบันทึก และคุณขอใหม่ได้ทุกเมื่อ',
  'Revision {0}': 'ฉบับปรับปรุงที่ {0}',
  'Replaces your current week. Days this plan leaves empty become rest days.': 'แทนที่สัปดาห์ปัจจุบันของคุณ วันที่แผนนี้เว้นว่างจะกลายเป็นวันพัก',
  'Could not apply those changes': 'ไม่สามารถนำการเปลี่ยนแปลงเหล่านั้นไปใช้ได้',
  'Dismiss these suggestions?': 'ปัดข้อเสนอแนะเหล่านี้ทิ้งหรือไม่',
  'Nothing changes, and the Coach will remember you turned these down.': 'ไม่มีอะไรเปลี่ยน และโค้ชจะจำไว้ว่าคุณปฏิเสธข้อเสนอเหล่านี้',
  'Dismiss': 'ปัดทิ้ง',
  'Based on your last {0} sessions': 'จาก {0} เซสชันล่าสุดของคุณ',
  'Your plan changed since the Coach looked at it. Suggestions that no longer match are greyed out. Ask for a fresh review to see them again.': 'แผนของคุณเปลี่ยนไปตั้งแต่โค้ชดูครั้งล่าสุด ข้อเสนอที่ไม่ตรงกันแล้วจะเป็นสีเทา ขอรีวิวใหม่เพื่อดูอีกครั้ง',
  'Doesn’t match your plan any more, so it can’t be applied.': 'ไม่ตรงกับแผนของคุณแล้ว จึงนำไปใช้ไม่ได้',
  'Apply nothing': 'ไม่นำไปใช้',
  'Dismiss all': 'ปัดทิ้งทั้งหมด',
  'Reverted the last Coach changes.': 'ย้อนกลับการเปลี่ยนแปลงล่าสุดของโค้ชแล้ว',
  'Before the Coach’s plan': 'ก่อนแผนของโค้ช',
  'Before the Coach’s changes': 'ก่อนการเปลี่ยนแปลงของโค้ช',
