  'Rough day? {0} will keep. Tomorrow is a fresh start.': 'วันนี้เหนื่อยเหรอ? {0} รอได้ พรุ่งนี้เริ่มใหม่',
  'Hey, {0} didn’t happen today. All good?': 'เฮ้ วันนี้ไม่ได้เล่น {0} ทุกอย่างโอเคไหม?',
  'I miss you': 'คิดถึงคุณนะ',
  '{0} waited by the door all evening. For you.': '{0} รอคุณอยู่ที่ประตูทั้งคืน รอคุณคนเดียว',
  'The barbell asked about you today. I didn’t know what to say.': 'วันนี้บาร์เบลถามถึงคุณ ฉันไม่รู้จะตอบว่าอะไร',
  'Was it something I said? {0} misses you.': 'ฉันพูดอะไรผิดไปหรือเปล่า? {0} คิดถึงคุณนะ',
  'I saved you a spot on the bench. It’s still empty.': 'ฉันจองที่บนม้านั่งไว้ให้คุณ ตอนนี้ยังว่างอยู่เลย',
  'Attention, recruit!': 'แถวตรง พลทหาร!',
  'Your gains are packing their bags. {0} tomorrow, no excuses!': 'กล้ามของคุณกำลังเก็บกระเป๋าหนี พรุ่งนี้ {0} ห้ามมีข้ออ้าง!',
