  'To answer, this device sends this straight to {0}, an AI service outside openGym, with your API key:': 'เพื่อจะตอบ อุปกรณ์นี้จะส่งข้อมูลนี้ตรงไปที่ {0} ซึ่งเป็นบริการ AI ภายนอก openGym โดยใช้คีย์ API ของคุณ:',
