  'Most lifts in the library use “{0}”, a few use “{1}”. A short bar for all of them means setting both.': 'ท่าส่วนใหญ่ในคลังใช้ “{0}” บางท่าใช้ “{1}” ถ้าจะใช้บาร์สั้นทุกท่า ให้ตั้งทั้งสองอย่าง',
