  'That’s 20 gyms, the most a phone can watch.': 'ครบ 20 ยิมแล้ว มือถือเฝ้าได้มากสุดเท่านี้',
  'The phone itself watches the gyms you added and only wakes openGym when you arrive. No tracking in between, and your locations never leave this phone.': 'มือถือเฝ้ายิมที่คุณเพิ่มไว้เอง และปลุก openGym เฉพาะตอนคุณมาถึง ไม่มีการติดตามระหว่างนั้น และสถานที่ของคุณไม่เคยออกจากมือถือเครื่องนี้',
  'The reminder needs location access in the background. You can allow it in the phone’s settings.': 'การเตือนต้องใช้ตำแหน่งเบื้องหลัง อนุญาตได้ในการตั้งค่าของมือถือ',
  'To notice that you walked into your gym while openGym is closed, the phone needs to let it see your location in the background.': 'เพื่อให้รู้ว่าคุณเดินเข้ายิมขณะที่ openGym ปิดอยู่ มือถือต้องให้มันเห็นตำแหน่งของคุณในเบื้องหลัง',
  'Until': 'ถึง',
  'Walk into one of your gyms and openGym nudges you to hit Start. Once a day at most, and never when you already trained. Your gyms stay on this phone.': 'เดินเข้ายิมของคุณแล้ว openGym จะสะกิดให้กดเริ่ม วันละครั้งเป็นอย่างมาก และไม่เตือนถ้าคุณออกกำลังไปแล้ว ยิมของคุณอยู่บนมือถือเครื่องนี้เท่านั้น',
  'Without background location the phone can’t spot your gym while openGym is closed.': 'ถ้าไม่มีตำแหน่งเบื้องหลัง มือถือจะจำยิมของคุณไม่ได้ขณะที่ openGym ปิดอยู่',
