  'One row per set, for Excel, Sheets, your coach or another app. openGym reads it back too.': 'หนึ่งแถวต่อเซ็ต สำหรับ Excel, Sheets, โค้ชของคุณ หรือแอปอื่น openGym ก็อ่านกลับได้เหมือนกัน',
