  'I own no dumbbells': 'ฉันไม่มีดัมเบล',
  'Dumbbell lifts stay out of the library, the picker and the Coach’s plans.': 'ท่าที่ใช้ดัมเบลจะไม่อยู่ในคลัง ตัวเลือก และแผนของโค้ช',
