  'openGym reads only while it is open: heart rate for workouts of the last day, weigh-ins of the last year. Older workouts stay as they are.': 'openGym อ่านเฉพาะตอนที่เปิดอยู่: อัตราการเต้นของหัวใจของการฝึกในวันล่าสุด และน้ำหนักในหนึ่งปีล่าสุด การฝึกที่เก่ากว่านั้นจะเหมือนเดิม',
  // --- seasonal themes (lib/seasonal.js) ---
  'Also during workouts': 'ระหว่างออกกำลังกายด้วย',
  'A cobweb in the header, bats behind the rest timer, pumpkins on the finish screen. Never on your sets.': 'ใยแมงมุมที่ส่วนหัว ค้างคาวหลังตัวจับเวลาพัก ฟักทองตอนจบ ไม่บังเซ็ตของคุณเด็ดขาด',
  'Seasonal themes': 'ธีมตามฤดูกาล',
  'Little extras for the time of year.': 'ของตกแต่งเล็กๆ ตามช่วงเวลาของปี',
  'Halloween': 'ฮาโลวีน',
  'Auto': 'อัตโนมัติ',
  'Spooky colors': 'สีสยองขวัญ',
  'A pumpkin orange accent while Halloween shows. Your own color comes back after.': 'สีเน้นส้มฟักทองระหว่างช่วงฮาโลวีน หลังจากนั้นสีของคุณจะกลับมา',
  'Spiders, bats and one shy pumpkin until the end of October. Never during a workout.': 'แมงมุม ค้างคาว และฟักทองขี้อายหนึ่งลูกจนถึงสิ้นเดือนตุลาคม ไม่โผล่ระหว่างออกกำลังกายเด็ดขาด',
  'Back next October. The spiders are on holiday.': 'กลับมาตุลาคมปีหน้า แมงมุมไปพักร้อนอยู่',
  'On all year round. Bold choice.': 'เปิดตลอดทั้งปี กล้ามาก',
  'Off, even in season. Fair enough.': 'ปิด แม้ในช่วงเทศกาล ก็ได้',
  'Boo! You found the pumpkin. It was watching you train.': 'แฮ่! คุณเจอฟักทองแล้ว มันแอบดูคุณซ้อมอยู่',
  'Boo! Pumpkin found. Your next PR is now officially haunted.': 'แฮ่! เจอฟักทองแล้ว สถิติครั้งหน้าของคุณมีผีสิงอย่างเป็นทางการ',
  'Boo! The bats were not part of the warm-up.': 'แฮ่! ค้างคาวไม่ได้อยู่ในการวอร์มอัพนะ',
  'Boo! Found it. The spiders owe you a rep.': 'แฮ่! เจอแล้ว แมงมุมติดคุณหนึ่งครั้ง',
  'The pumpkin is napping. Come back tomorrow.': 'ฟักทองกำลังงีบ พรุ่งนี้มาใหม่นะ',
