  'That one is unwrapped. A new present turns up tomorrow.': 'ของขวัญชิ้นนี้แกะแล้ว พรุ่งนี้จะมีของขวัญชิ้นใหม่มาให้',
  'Festive icon on. Very fetching.': 'เปิดไอคอนเทศกาลแล้ว น่ารักมาก',
  'Fancy a festive icon?': 'อยากได้ไอคอนเทศกาลไหม',
  'The barbell has put on its Santa hat. Just for this phone, and you can switch back in Settings any time.': 'บาร์เบลสวมหมวกซานต้าแล้ว ใช้กับโทรศัพท์เครื่องนี้เท่านั้น และสลับกลับได้ทุกเมื่อในตั้งค่า',
