  'Door {0} is still waiting': 'ประตูบานที่ {0} ยังรออยู่',
  'All 24 doors open. Merry everything!': 'เปิดครบ 24 บานแล้ว สุขสันต์ทุกเทศกาล!',
  'All caught up. See you tomorrow!': 'ครบหมดแล้ว พรุ่งนี้เจอกัน!',
  'Advent calendar': 'ปฏิทินนับถอยหลังคริสต์มาส',
  '{0} of 24 doors open': 'เปิดแล้ว {0} จาก 24 บาน',
  'No peeking 👀': 'ห้ามแอบดู 👀',
  'One door a day until the 24th. Missed one? It waits for you.': 'วันละหนึ่งบานจนถึงวันที่ 24 พลาดไปหรือ ประตูรอคุณอยู่',
