  'No programmes yet. Make one from your plan, or grab a starter below.': 'ยังไม่มีโปรแกรม สร้างจากแผนของคุณ หรือเลือกโปรแกรมเริ่มต้นด้านล่าง',
  'No schedule yet. Put routines on your week or in a loop in Plan, then take it over here.': 'ยังไม่มีตาราง ใส่รูทีนในสัปดาห์หรือการหมุนเวียนในแผน แล้วนำมาใช้ที่นี่',
  'Nothing set, progression as usual': 'ไม่ได้ตั้งค่า เพิ่มระดับตามปกติ',
