  'Strength block, 4 weeks': 'บล็อกความแข็งแรง 4 สัปดาห์',
  'The schedule in your plan right now becomes this programme’s.': 'ตารางที่อยู่ในแผนของคุณตอนนี้จะกลายเป็นของโปรแกรมนี้',
  'The week is the calendar week: week 1 is the one you start in. A pause holds it.': 'สัปดาห์คือสัปดาห์ตามปฏิทิน: สัปดาห์ที่ 1 คือสัปดาห์ที่คุณเริ่ม การพักไว้จะหยุดไว้ก่อน',
  'This programme is gone.': 'โปรแกรมนี้ไม่มีแล้ว',
  'Three days of plain linear progression, with a deload every fourth week.': 'สามวันของการเพิ่มระดับแบบเส้นตรงธรรมดา ดีโหลดทุกสัปดาห์ที่สี่',
  'Three days on the 5×5 routines, a little heavier every week, then a light week to bounce back.': 'สามวันกับรูทีน 5×5 หนักขึ้นทีละนิดทุกสัปดาห์ แล้วตามด้วยสัปดาห์เบาให้ฟื้นตัว',
  'Upper / lower by effort, 6 weeks': 'ส่วนบน / ส่วนล่างตามความหนัก 6 สัปดาห์',
  'Use my current plan': 'ใช้แผนปัจจุบันของฉัน',
