  'Your routines as a block of weeks, each week with its own %1RM or RPE.': 'รูทีนของคุณเป็นบล็อกหลายสัปดาห์ แต่ละสัปดาห์มี %1RM หรือ RPE ของตัวเอง',
  'Your routines as a block of weeks, with starter programmes to try.': 'รูทีนของคุณเป็นบล็อกหลายสัปดาห์ พร้อมโปรแกรมเริ่มต้นให้ลอง',
