  "Workout settings, layouts, notes and extra exercises hide in here.": "การตั้งค่าเวิร์กเอาต์ เลย์เอาต์ โน้ต และท่าเพิ่มเติมซ่อนอยู่ในนี้",
  "Workouts, streaks and everything you’ve lifted. It fills up as you train.": "เวิร์กเอาต์ สถิติต่อเนื่อง และทุกอย่างที่คุณยก จะเต็มขึ้นเมื่อคุณฝึก",
  "You stopped halfway. Want to see the rest?": "คุณหยุดไว้ครึ่งทาง ดูที่เหลือไหม?",
