  "One more": "อีกอันเดียว",
  "Open a check-in to change or delete it. Progress photos work the same way.": "เปิดรายการวัดสัดส่วนเพื่อแก้หรือลบ รูปความคืบหน้าก็ใช้แบบเดียวกัน",
  "Open a workout": "เปิดการออกกำลังกาย",
  "Optional: your own picture or clip of the setup. Handy for that one weird machine.": "ไม่บังคับ: รูปหรือคลิปการตั้งเครื่องของคุณเอง สะดวกมากกับเครื่องแปลกๆ เครื่องนั้น",
  "Pick a backup file and it’s all back.": "เลือกไฟล์สำรอง แล้วทุกอย่างก็กลับมา",
  "Pick one. Muscle groups are optional, but they feed the body map and muscle balance.": "เลือกหนึ่งอย่าง กลุ่มกล้ามเนื้อไม่บังคับ แต่จะช่วยแผนที่ร่างกายและความสมดุลของกล้ามเนื้อ",
  "Pick your exercises": "เลือกท่าของคุณ",
  "Practice copy gone": "ลบสำเนาซ้อมแล้ว",
  "Practice session": "เซสชันซ้อม",
  "Push Day, Legs, Monday Misery. Tap the name and type your own.": "วันดัน วันขา วันจันทร์ทรมาน แตะที่ชื่อแล้วพิมพ์ของคุณเอง",
  "Reopens it: sets, weights, reps, exercises. Nothing changes until you tap Save.": "เปิดขึ้นมาใหม่: เซ็ต น้ำหนัก จำนวนครั้ง ท่า จะไม่มีอะไรเปลี่ยนจนกว่าคุณจะแตะ “บันทึก”",
  "Restore a backup": "กู้คืนข้อมูลสำรอง",
