  "Save your plan?": "บันทึกแผนของคุณไหม?",
  "Saved!": "บันทึกแล้ว!",
  "Search finds your exercises like any other, and they go into routines and workouts the same way.": "การค้นหาเจอท่าของคุณเหมือนท่าอื่น และใส่ในรูทีนกับการออกกำลังกายได้แบบเดียวกัน",
  "Settings are on Home": "ตั้งค่าอยู่ที่หน้าหลัก",
  "Share weigh-ins and workouts with the phone’s health app.": "แชร์บันทึกน้ำหนักและการออกกำลังกายกับแอปสุขภาพของมือถือ",
  "So the equipment filter and your gym profiles know about it.": "เพื่อให้ตัวกรองอุปกรณ์และโปรไฟล์ยิมของคุณรู้จักมัน",
  "Spreadsheet": "สเปรดชีต",
  "Strong, Hevy, FitNotes, GymMane or Apple Health body weight: import their export here.": "น้ำหนักตัวจาก Strong, Hevy, FitNotes, GymMane หรือ Apple Health: นำเข้าไฟล์ที่ส่งออกจากแอปเหล่านั้นได้ที่นี่",
  "Syncing lives under your account. Tap back to Settings.": "การซิงก์อยู่ใต้บัญชีของคุณ แตะย้อนกลับไปที่ “ตั้งค่า”",
  "Syncing your devices through your own openGym server lives under your account. No server? Everything still works on this device.": "การซิงก์อุปกรณ์ผ่านเซิร์ฟเวอร์ openGym ของคุณเองอยู่ใต้บัญชีของคุณ ไม่มีเซิร์ฟเวอร์? ทุกอย่างยังใช้ได้บนเครื่องนี้",
  "Tap Add and pick your new routine. The loop runs in that order.": "แตะ “เพิ่ม” แล้วเลือกรูทีนใหม่ การหมุนเวียนจะวนตามลำดับนั้น",
  "Tap Add exercise to pick what goes in.": "แตะ “เพิ่มท่าออกกำลังกาย” เพื่อเลือกสิ่งที่จะใส่",
  "Tap All weigh-ins.": "แตะ “บันทึกน้ำหนักทั้งหมด”",
  "Tap Create exercise when it looks right. Or Next to just look around.": "ถ้าดูโอเคแล้วแตะ “สร้างท่าออกกำลังกาย” หรือแตะ “ถัดไป” เพื่อแค่ดูรอบๆ",
  "Tap New routine. It stays a draft until you save it.": "แตะ “รูทีนใหม่” มันจะเป็นฉบับร่างจนกว่าคุณจะบันทึก",
  "Tap Schedule to put it on a day.": "แตะ “ตารางเวลา” เพื่อใส่มันลงในวัน",
  "Tap a weekday and choose your new routine. Two on one day works too.": "แตะวันในสัปดาห์แล้วเลือกรูทีนใหม่ วันเดียวสองรูทีนก็ได้",
  "Tap an exercise any time to change sets, reps or weight. The arrows reorder, the link makes a superset.": "แตะท่าได้ทุกเมื่อเพื่อเปลี่ยนเซ็ต จำนวนครั้ง หรือน้ำหนัก ลูกศรใช้จัดลำดับ ลิงก์ใช้ทำซูเปอร์เซ็ต",
  "Tap back to Settings.": "แตะย้อนกลับไปที่ “ตั้งค่า”",
  "Tap back.": "แตะย้อนกลับ",
  "Tap it.": "แตะเลย",
  "Tap one to set its sets, reps and weight, or + to take the usual. Close the list when you’re done.": "แตะท่าเพื่อตั้งเซ็ต จำนวนครั้ง และน้ำหนัก หรือแตะ + เพื่อใช้ค่าปกติ เสร็จแล้วปิดรายการได้เลย",
  "That’s a plan": "นี่แหละแผน",
  "That’s the lot": "ครบแล้ว",
  "The bin deletes one, and Undo pops up right after. Wrong number? Log that day again and the new one wins.": "ถังขยะลบทีละรายการ แล้ว “เลิกทำ” จะเด้งขึ้นมาทันที ตัวเลขผิด? บันทึกวันนั้นใหม่ อันใหม่ชนะ",
