  "Mostly in the morning. The early bird gets the barbell.": "ส่วนใหญ่ฝึกตอนเช้า ตื่นเช้าได้บาร์เบลก่อน",
  "Mostly around lunch. Who needs a lunch break anyway?": "ส่วนใหญ่ฝึกช่วงเที่ยง พักกลางวันไว้ทำไม จริงไหม",
  "Mostly in the afternoon. The sweet spot.": "ส่วนใหญ่ฝึกตอนบ่าย ช่วงเวลาที่ลงตัวที่สุด",
  "Mostly in the evening. Work, then work out.": "ส่วนใหญ่ฝึกตอนเย็น เลิกงานแล้วไปออกแรงต่อ",
