  "Early bird": "นกตื่นเช้า",
  "Most of your sessions started before 9. The sun was still catching up.": "การฝึกส่วนใหญ่ของคุณเริ่มก่อน 9 โมง พระอาทิตย์ยังตามไม่ทันเลย",
  "Night owl": "นกฮูกกลางคืน",
  "Most of your sessions started after 8 pm. The quiet gym is your gym.": "การฝึกส่วนใหญ่ของคุณเริ่มหลัง 2 ทุ่ม ยิมเงียบ ๆ คือยิมของคุณ",
  "Leg-day loyalist": "สาวกวันขา",
