  "Clockwork": "ตรงเป๊ะเหมือนนาฬิกา",
  "Week after week after week. Your calendar knows your name.": "สัปดาห์แล้วสัปดาห์เล่า ปฏิทินจำชื่อคุณได้แล้ว",
  "Record breaker": "นักทำลายสถิติ",
  "So many new bests, your trophy shelf needs a trophy shelf.": "สถิติใหม่เยอะจนชั้นวางถ้วยรางวัลต้องมีชั้นวางถ้วยรางวัลอีกที",
