  "In it for the long haul": "สายลากยาว",
  "Long sessions, no rush. The gym is basically your second home.": "ฝึกนาน ๆ ไม่รีบ ยิมแทบจะเป็นบ้านหลังที่สองของคุณ",
  "In and out": "มาไวไปไว",
